     1|/**
     2| * IVX Task Execution State Machine
     3| *
     4| * Owner mandate 2026-07-20 Phase 1: replace the simplified task status logic
     5| * with a real 17-state state machine that enforces legal transitions and the
     6| * owner's completion rules.
     7| *
     8| * Rules (enforced in canTransition + assertCanTransition):
     9| *   - DEPLOYED means only that a deployment occurred.
    10| *   - VERIFIED means the requested acceptance tests passed.
    11| *   - A task cannot become VERIFIED from /health alone.
    12| *   - A development task cannot become VERIFIED when no code changed unless the
    13| *     system proves that configuration, data, infrastructure, or an external
    14| *     dependency was the actual cause.
    15| *   - If no work was completed, status must be BLOCKED, FAILED, or
    16| *     NO_CHANGE_REQUIRED.
    17| *   - Never display "development completed" when the code diff is empty.
    18| *
    19| * This module is intentionally runtime-free and does NOT import worker types,
    20| * to avoid circular dependencies.
    21| */
    22|
    23|export const IVX_TASK_STATE_MACHINE_MARKER = 'ivx-task-state-machine-2026-07-20';
    24|
    25|export type IVXTaskState =
    26|  | 'RECEIVED'
    27|  | 'ANALYZING'
    28|  | 'REPRODUCING'
    29|  | 'ROOT_CAUSE_IDENTIFIED'
    30|  | 'IMPLEMENTING'
    31|  | 'CODE_CHANGED'
    32|  | 'TESTING'
    33|  | 'QA_REQUIRED'
    34|  | 'QA_IN_PROGRESS'
    35|  | 'READY_TO_DEPLOY'
    36|  | 'DEPLOYING'
    37|  | 'DEPLOYED'
    38|  | 'PRODUCTION_VERIFYING'
    39|  | 'VERIFIED'
    40|  | 'BLOCKED'
    41|  | 'FAILED'
    42|  | 'NO_CHANGE_REQUIRED';
    43|
    44|export const ALL_TASK_STATES: readonly IVXTaskState[] = [
    45|  'RECEIVED',
    46|  'ANALYZING',
    47|  'REPRODUCING',
    48|  'ROOT_CAUSE_IDENTIFIED',
    49|  'IMPLEMENTING',
    50|  'CODE_CHANGED',
    51|  'TESTING',
    52|  'QA_REQUIRED',
    53|  'QA_IN_PROGRESS',
    54|  'READY_TO_DEPLOY',
    55|  'DEPLOYING',
    56|  'DEPLOYED',
    57|  'PRODUCTION_VERIFYING',
    58|  'VERIFIED',
    59|  'BLOCKED',
    60|  'FAILED',
    61|  'NO_CHANGE_REQUIRED',
    62|] as const;
    63|
    64|export const TERMINAL_TASK_STATES: ReadonlySet<IVXTaskState> = new Set([
    65|  'VERIFIED',
    66|  'BLOCKED',
    67|  'FAILED',
    68|  'NO_CHANGE_REQUIRED',
    69|]);
    70|
    71|/**
    72| * Legal forward transitions. A task may not skip from RECEIVED straight to
    73| * DEPLOYED or VERIFIED — it must walk the senior-developer loop.
    74| */
    75|const LEGAL_TRANSITIONS: ReadonlyMap<IVXTaskState, ReadonlySet<IVXTaskState>> = new Map([
    76|  ['RECEIVED', new Set(['ANALYZING', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    77|  ['ANALYZING', new Set(['REPRODUCING', 'ROOT_CAUSE_IDENTIFIED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    78|  ['REPRODUCING', new Set(['ROOT_CAUSE_IDENTIFIED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    79|  ['ROOT_CAUSE_IDENTIFIED', new Set(['IMPLEMENTING', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    80|  ['IMPLEMENTING', new Set(['CODE_CHANGED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    81|  ['CODE_CHANGED', new Set(['TESTING', 'BLOCKED', 'FAILED'])],
    82|  ['TESTING', new Set(['QA_REQUIRED', 'READY_TO_DEPLOY', 'BLOCKED', 'FAILED'])],
    83|  ['QA_REQUIRED', new Set(['QA_IN_PROGRESS', 'BLOCKED', 'FAILED'])],
    84|  ['QA_IN_PROGRESS', new Set(['READY_TO_DEPLOY', 'BLOCKED', 'FAILED'])],
    85|  ['READY_TO_DEPLOY', new Set(['DEPLOYING', 'BLOCKED', 'FAILED'])],
    86|  ['DEPLOYING', new Set(['DEPLOYED', 'BLOCKED', 'FAILED'])],
    87|  ['DEPLOYED', new Set(['PRODUCTION_VERIFYING', 'BLOCKED', 'FAILED'])],
    88|  ['PRODUCTION_VERIFYING', new Set(['VERIFIED', 'BLOCKED', 'FAILED'])],
    89|  ['VERIFIED', new Set()],
    90|  ['BLOCKED', new Set()],
    91|  ['FAILED', new Set()],
    92|  ['NO_CHANGE_REQUIRED', new Set()],
    93|]);
    94|
    95|/**
    96| * Transition guard: verifies a transition is legal per the state machine.
    97| * Also enforces the owner's completion rules:
    98| *   - A development task cannot transition to VERIFIED with an empty diff
    99| *     unless an external cause is proven.
   100| *   - A task cannot transition to VERIFIED from /health alone (requires
   101| *     featureVerificationOk).
   102| *   - A task cannot transition to VERIFIED with no deployment for development
   103| *     tasks.
   104| */
   105|export type IVXTransitionGuardInput = {
   106|  from: IVXTaskState;
   107|  to: IVXTaskState;
   108|  isDevelopmentTask: boolean;
   109|  filesChangedCount: number;
   110|  testsRun: boolean;
   111|  testsPassed: boolean;
   112|  deployId: string | null;
   113|  productionHealthOk: boolean;
   114|  featureVerificationOk: boolean | null;
   115|  externalCauseProven: boolean;
   116|};
   117|
   118|export type IVXTransitionGuardResult = {
   119|  ok: boolean;
   120|  legal: boolean;
   121|  reasons: string[];
   122|  from: IVXTaskState;
   123|  to: IVXTaskState;
   124|};
   125|
   126|export function isTerminalTaskState(state: IVXTaskState): boolean {
   127|  return TERMINAL_TASK_STATES.has(state);
   128|}
   129|
   130|export function canTransition(from: IVXTaskState, to: IVXTaskState): boolean {
   131|  const allowed = LEGAL_TRANSITIONS.get(from);
   132|  return allowed ? allowed.has(to) : false;
   133|}
   134|
   135|export function assertCanTransition(input: IVXTransitionGuardInput): IVXTransitionGuardResult {
   136|  const reasons: string[] = [];
   137|  const { from, to } = input;
   138|
   139|  // Check structural legality first.
   140|  if (!canTransition(from, to)) {
   141|    reasons.push(`Illegal transition: ${from} -> ${to} is not a permitted forward transition.`);
   142|    return { ok: false, legal: false, reasons, from, to };
   143|  }
   144|
   145|  // Enforce completion rules on entry to VERIFIED.
   146|  if (to === 'VERIFIED') {
   147|    if (input.isDevelopmentTask) {
   148|      if (input.filesChangedCount === 0 && !input.externalCauseProven) {
   149|        reasons.push(
   150|          'A development task cannot become VERIFIED when no code changed unless an external cause (config/data/infra) is proven.',
   151|        );
   152|        return { ok: false, legal: true, reasons, from, to };
   153|      }
   154|      if (input.filesChangedCount === 0 && input.externalCauseProven && !input.deployId) {
   155|        reasons.push('External-cause development task requires a deployment before VERIFIED.');
   156|        return { ok: false, legal: true, reasons, from, to };
   157|      }
   158|      if (input.filesChangedCount > 0) {
   159|        if (!input.testsRun) {
   160|          reasons.push('Files changed but tests were not run — cannot become VERIFIED.');
   161|          return { ok: false, legal: true, reasons, from, to };
